export default async (): Promise<RequestMessage> => (
{
  // gv.request.params is whatever the caller passed for THIS run — the CLI's
  // --param, the MCP tool's `params`, or the second argument of gv.invoke().
  // Empty on a plain run, so give every param a default.
  message: gv.request.params.message ?? "hello from params",
  count: Number(gv.request.params.count ?? 1),
}
)
